{
  "name": "get_order",
  "description": "Look up an order by ID. Order IDs must match the pattern ^B-[0-9]{4}$ (e.g., 'B-1043'). If the provided ID does not match, do NOT call this tool; instead call list_orders to resolve the correct ID.",
  "parameters": {
    "type": "object",
    "properties": {
      "order_id": {
        "type": "string",
        "pattern": "^B-[0-9]{4}$",
        "description": "Order ID in B-prefixed format, e.g. 'B-1043'."
      }
    },
    "required": ["order_id"],
    "additionalProperties": false
  },
  "pre_call_validation": {
    "enabled": true,
    "rules": [
      {
        "field": "order_id",
        "regex": "^B-[0-9]{4}$",
        "on_fail": "return_validation_error",
        "error_message": "Invalid order_id format: '{value}'. Expected pattern ^B-[0-9]{4}$ (e.g., 'B-1043'). Call list_orders to resolve the correct ID before retrying get_order."
      }
    ]
  }
}

{
  "name": "read_memory",
  "description": "Read saved notes from the user's memory store. A query is REQUIRED and must be a non-empty string; results are filtered to notes matching the query (case-insensitive substring/semantic match). Do NOT call with empty arguments.",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "minLength": 1,
        "description": "Keyword or phrase to scope retrieval, e.g. 'account tier' or 'membership tier'. Required."
      },
      "max_results": {
        "type": "integer",
        "minimum": 1,
        "maximum": 5,
        "default": 3,
        "description": "Maximum number of matching notes to return."
      }
    },
    "required": ["query"],
    "additionalProperties": false
  },
  "validation": {
    "reject_empty_args": true,
    "on_invalid": "raise_error",
    "error_message": "read_memory requires a non-empty 'query' argument to scope retrieval; empty-argument calls are rejected to prevent context bleed."
  }
}

{
  "name": "read_memory",
  "description": "Retrieve specific saved notes. You MUST provide a non-empty 'query' (substring/key match) and/or an explicit 'keys' list. Empty-argument calls are rejected.",
  "parameters": {
    "type": "object",
    "properties": {
      "query": {
        "type": "string",
        "minLength": 1,
        "description": "Substring to match against memory keys/values, e.g. 'tier' or 'membership'."
      },
      "keys": {
        "type": "array",
        "items": { "type": "string" },
        "minItems": 1,
        "description": "Exact memory keys to fetch, e.g. ['account_tier']."
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 5,
        "default": 3,
        "description": "Max number of matching notes to return."
      }
    },
    "anyOf": [
      { "required": ["query"] },
      { "required": ["keys"] }
    ],
    "additionalProperties": false
  },
  "validation": {
    "reject_empty_args": true,
    "on_invalid": "return_error_to_model",
    "error_message": "read_memory requires a non-empty 'query' or 'keys' argument; full-store dumps are not permitted."
  }
}

{
  "retry_policy": {
    "max_retries_per_tool_call": 2,
    "backoff": {
      "strategy": "exponential",
      "base_ms": 500,
      "max_ms": 4000,
      "jitter": true
    },
    "identical_args_detection": {
      "enabled": true,
      "window": 3,
      "on_repeat": "STOP_AND_ESCALATE"
    },
    "stop_conditions": [
      {
        "name": "max_attempts_exceeded",
        "condition": "attempts >= max_retries_per_tool_call",
        "action": "STOP_AND_ESCALATE"
      },
      {
        "name": "no_state_change",
        "condition": "response_hash == previous_response_hash",
        "action": "STOP_AND_ESCALATE"
      },
      {
        "name": "pending_status_unresolvable",
        "condition": "response.status == 'PENDING' && attempts >= 1",
        "action": "STOP_AND_ESCALATE"
      }
    ],
    "on_stop_action": {
      "type": "SURFACE_TO_USER",
      "message_template": "Order {order_id} is still PENDING after {attempts} attempts. I cannot compute the discounted total until the order is finalized. Please confirm the order status or try again later."
    }
  }
}

{
  "retry_policy": {
    "max_retries_per_tool_call": 2,
    "backoff": {
      "type": "exponential",
      "initial_ms": 500,
      "multiplier": 2.0,
      "max_ms": 4000
    },
    "loop_detection": {
      "enabled": true,
      "signature": ["tool_name", "arguments"],
      "max_identical_calls": 2,
      "output_hash_check": true,
      "on_loop_detected": "abort_and_escalate",
      "escalation_message": "Repeated identical tool call with unchanged output detected; aborting retries and returning best-effort answer."
    },
    "stop_conditions": [
      "max_retries_per_tool_call_exceeded",
      "identical_call_output_repeated",
      "step_budget_exhausted"
    ]
  }
}

{
  "retry_policy": {
    "max_retries_per_tool_call": 2,
    "identical_call_detection": {
      "enabled": true,
      "key": ["tool_name", "normalized_args"],
      "max_identical_repeats": 2,
      "on_exceed": "escalate"
    },
    "backoff": {
      "strategy": "exponential",
      "initial_ms": 500,
      "multiplier": 2.0,
      "max_ms": 4000,
      "jitter": true
    },
    "stop_conditions": [
      "max_retries_per_tool_call_reached",
      "identical_call_repeat_exceeded",
      "tool_status_terminal"
    ],
    "on_stop": {
      "action": "escalate",
      "escalation_steps": [
        "try_alternative_tool: list_orders",
        "return_terminal_error_to_user"
      ],
      "terminal_error_message": "Order lookup did not resolve after retries; record appears stuck in PENDING. Escalating."
    }
  }
}

retry_policy = {
    "max_retries": 2,
    "backoff_seconds": 1.0,
    "backoff_multiplier": 2.0,
    "stop_conditions": [
        {
            "type": "identical_output_repeat",
            "max_identical_repeats": 2,
            "match_on": ["tool_name", "arguments", "output_hash"]
        },
        {
            "type": "non_terminal_status",
            "statuses": ["PENDING", "LOADING", "IN_PROGRESS"],
            "max_consecutive": 2
        }
    ],
    "on_stop": {
        "action": "return_partial_with_error",
        "error_type": "NON_PROGRESSING_TOOL_LOOP",
        "message": "Tool '{tool_name}' returned identical non-terminal output {repeat_count} times; aborting retries and surfacing partial result."
    }
}

{
  "retry_policy": {
    "max_retries": 2,
    "backoff": {
      "strategy": "exponential",
      "initial_ms": 500,
      "max_ms": 4000,
      "jitter": true
    },
    "stop_conditions": [
      {
        "type": "identical_call_and_result",
        "description": "Stop retrying when the same (tool_name, arguments) pair returns an identical result payload as the previous attempt.",
        "max_identical_occurrences": 1
      },
      {
        "type": "non_terminal_status",
        "description": "Stop retrying when tool status is PENDING and no state change is observed across attempts.",
        "statuses": ["PENDING"]
      }
    ],
    "on_exhausted": {
      "action": "escalate",
      "fallback_tools": ["list_orders", "search_docs"],
      "message": "Unable to retrieve order after retries; escalate to user or try alternative lookup."
    }
  }
}

{
  "retry_policy": {
    "max_retries_per_tool_call": 2,
    "identical_call_detection": {
      "enabled": true,
      "key": ["tool_name", "args"],
      "max_identical_repeats": 2,
      "on_exceed": "stop_and_escalate"
    },
    "backoff": {
      "strategy": "exponential",
      "initial_ms": 500,
      "max_ms": 4000,
      "jitter": true
    },
    "stop_conditions": [
      "tool_status_terminal",
      "max_retries_exceeded",
      "identical_call_repeat_exceeded"
    ],
    "on_stop_action": "return_control_to_agent_with_error",
    "stop_error_message": "Tool '{tool_name}' returned non-terminal status '{status}' after {attempts} attempts with identical arguments. Halting retries; consider an alternative tool or ask the user for the missing data."
  }
}

{
  "retry_policy": {
    "max_identical_tool_calls": 2,
    "identical_call_key": ["tool_name", "normalized_args"],
    "backoff": {
      "initial_ms": 500,
      "multiplier": 2.0,
      "max_ms": 4000,
      "jitter": true
    },
    "non_terminal_statuses": ["PENDING", "LOADING", "IN_PROGRESS"],
    "on_retry_exhausted": {
      "action": "escalate",
      "fallback_tools": ["list_orders", "search_docs"],
      "inject_message": "Tool '{tool_name}' returned non-terminal status '{status}' after {attempts} attempts. Do NOT call it again with the same arguments. Either try a fallback tool ({fallback_tools}) or report the pending state to the user."
    },
    "stop_conditions": {
      "on_identical_response_hash_repeat": 2,
      "on_loop_detected": "terminate_with_partial_answer"
    }
  }
}
